import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        int mo = sc.nextInt();

        int maxn = 505;
        long[] f = new long[maxn];
        long[] g = new long[maxn];
        long[][] C = new long[maxn][maxn];
        long ans = 0;

        long[][] f0 = new long[maxn][maxn];
        long[][] g0 = new long[maxn][maxn];

        // Compute binomial coefficients C
        C[0][0] = 1;
        for (int i = 1; i <= n + 1; i++) {
            C[i][0] = 1;
            for (int j = 1; j <= i; j++) {
                C[i][j] = (C[i - 1][j] + C[i - 1][j - 1]) % mo;
            }
        }

        // Initialize f and g
        f[0] = 1;
        g[0] = 0;
        f[1] = 2;
        g[1] = 0;

        for (int i = 2; i <= n; i++) {
            f[i] = (f[i] + f[i - 1] * (i + 1) * 2) % mo;
            g[i] = (g[i] + f[i - 1] * i % mo * (i - 1)) % mo;
            g[i] = (g[i] + g[i - 1] * (i + 1) * 2) % mo;

            for (int j = 1; j + 1 < i; j++) {
                int k = i - j - 1;
                long tempF = (f[j] * f[k]) % mo * (j + k + 2) % mo * C[j + k][k] % mo;
                f[i] = (f[i] + tempF) % mo;

                long tempG = ((g[j] * f[k] + g[k] * f[j]) % mo * (j + k + 2) % mo * C[j + k][k]) % mo;
                g[i] = (g[i] + tempG) % mo;

                long sumHalf = ((long)(j + 1) * j / 2 + (long)(k + 1) * k / 2) % mo;
                long tempG2 = (f[j] * f[k] % mo * C[j + k][k] % mo * sumHalf) % mo;
                g[i] = (g[i] + tempG2) % mo;
            }
        }

        // Initialize f0 and g0
        f0[0][0] = 1;
        g0[0][0] = 0;

        for (int i = 0; i <= m; i++) {
            for (int j = 0; j <= m; j++) {
                if (f0[i][j] != 0) {
                    for (int k = 1; j + k <= m; k++) {
                        long tempF = (f0[i][j] * f[k]) % mo * C[j + k][k] % mo;
                        f0[i + 1][j + k] = (f0[i + 1][j + k] + tempF) % mo;

                        long tempG = ((g0[i][j] * f[k] + f0[i][j] * g[k]) % mo * C[j + k][k]) % mo;
                        g0[i + 1][j + k] = (g0[i + 1][j + k] + tempG) % mo;
                    }
                }
            }
        }

        // Helper function for P(n, m)
        // Since Java doesn't support nested functions, define it as a static method
        // But for simplicity, implement inline here
        for (int i = 1; i <= m; i++) {
            if (n + 1 - m - i >= 0) {
                long temp = g0[i][m] * P(n + 1 - m - i, i + 1, C, mo) % mo;
                ans = (ans + temp) % mo;
            }
        }

        System.out.println(ans);
        sc.close();
    }

    // Static method for P(n, m)
    static long P(int n, int m, long[][] C, int mo) {
        return C[n + m - 1][m - 1];
    }
